import NIOCore
import Testing

@testable import WhiteThroatedHTTP1

private func viewTestHead(name: [UInt8], value: [UInt8]) -> WTHTTP1RequestHead {
    var storage = ByteBufferAllocator().buffer(capacity: 64 + name.count + value.count)
    storage.writeBytes(Array(repeating: UInt8(0x2e), count: 7))
    let methodStart = storage.writerIndex
    storage.writeString("GET")
    let uriStart = storage.writerIndex
    storage.writeString("/x")
    let nameStart = storage.writerIndex
    storage.writeBytes(name)
    let valueStart = storage.writerIndex
    storage.writeBytes(value)
    storage.moveReaderIndex(to: 7)
    return WTHTTP1RequestHead(
        storage: storage,
        methodRange: methodStart..<(methodStart + 3),
        uriRange: uriStart..<(uriStart + 2),
        version: .http11,
        headerNameRanges: [nameStart..<(nameStart + name.count)],
        headerValueRanges: [valueStart..<(valueStart + value.count)]
    )
}

