            let head = viewTestHead(name: name, value: value)
            #expect(head.storage.readerIndex == 7)
            #expect(head.headerNameRanges[0].lowerBound > 7)
            #expect(Array(head.headerNameView(at: 0)) == name)
            #expect(Array(head.headerValueView(at: 0)) == value)
            #expect(head.headerValueView(at: 0).count == length)
            #expect(head.method == .get)
            #expect(head.uriBytes() == Array("/x".utf8))
        }
    }

    @Test func viewsKeepSnapshotAcrossHeadAndOwnedArrayMutation() {
        let original = Array("original-value".utf8)
        var head = viewTestHead(name: Array("X-Snapshot".utf8), value: original)
        let nameView = head.headerNameView(at: 0)
        let valueView = head.headerValueView(at: 0)
        var owned = head.headerValue(at: 0)
        let replacement = Array(repeating: UInt8(0x7a), count: original.count)
        head.storage.setBytes(replacement, at: head.headerValueRanges[0].lowerBound)
        head.headerNameRanges[0] = head.uriRange
        owned[0] = 0x51
        #expect(Array(valueView) == original)
        #expect(Array(nameView) == Array("X-Snapshot".utf8))
        #expect(head.headerValue(at: 0) == replacement)
        #expect(Array(head.headerNameView(at: 0)) == Array("/x".utf8))
        #expect(owned != Array(valueView))
    }

    @Test func viewsRetainStorageAfterHeadScopeEnds() {
        func snapshot() -> ByteBufferView {
            viewTestHead(name: Array("X-Life".utf8), value: Array("retained".utf8))
                .headerValueView(at: 0)
        }
        let view = snapshot()
        #expect(Array(view) == Array("retained".utf8))
    }

    @Test func pipelinedViewsSurviveInputReuse() throws {
        var buffer = ByteBuffer(string:
            "GET /a HTTP/1.1\r\nX-Step: first\r\n\r\n"
                + "GET /b HTTP/1.1\r\nX-Step: second\r\n\r\n"
        )
        let parser = WTHTTP1Parser()
        let first = try #require(try parser.parseHead(from: &buffer))
        let firstView = first.headerValueView(at: 0)
        let second = try #require(try parser.parseHead(from: &buffer))
        let secondView = second.headerValueView(at: 0)
        buffer.clear()
        buffer.writeBytes(Array(repeating: UInt8(0x7a), count: 1024))
        #expect(Array(firstView) == Array("first".utf8))
        #expect(Array(secondView) == Array("second".utf8))
    }
