import Foundation
import NIOCore
import NIOHTTP1
import XCTest

@testable import WhiteThroatedHTTP1

final class WTHTTP1HeaderViewBenchmarkTests: XCTestCase {
    func testHeaderDecodingBenchmark() throws {
        let environment = ProcessInfo.processInfo.environment
        try XCTSkipUnless(environment["WHITETHROATED_HEADER_VIEW_BENCHMARK"] == "1")
        let iterations = Int(environment["WHITETHROATED_HEADER_VIEW_ITERATIONS"] ?? "100000") ?? 100000
        precondition(iterations > 0)
        var input = ByteBuffer(string: "GET / HTTP/1.1\r\nHost: example.com\r\nX-Text: café\r\nX-Empty:\r\n\r\n")
        let head = try XCTUnwrap(try WTHTTP1Parser().parseHead(from: &input))
        func decode(views: Bool) -> HTTPHeaders {
            var headers = HTTPHeaders()
            headers.reserveCapacity(head.headerCount)
            for index in 0..<head.headerCount {
                if views {
                    headers.add(
                        name: String(decoding: head.headerNameView(at: index), as: UTF8.self),
                        value: String(decoding: head.headerValueView(at: index), as: UTF8.self)
                    )
                } else {
                    headers.add(
                        name: String(decoding: head.headerName(at: index), as: UTF8.self),
                        value: String(decoding: head.headerValue(at: index), as: UTF8.self)
                    )
                }
            }
            return headers
        }
        XCTAssertEqual(decode(views: false), decode(views: true))
        var checksums = [0, 0]
        var samples = [[Double](), [Double]()]
        func step(_ mode: Int) {
            for header in decode(views: mode == 1) {
                checksums[mode] &+= header.name.utf8.count + header.value.utf8.count
            }
        }
        for mode in 0...1 { for _ in 0..<1000 { step(mode) } }
        for round in 0..<6 {
            for mode in round.isMultiple(of: 2) ? [0, 1] : [1, 0] {
                let start = DispatchTime.now().uptimeNanoseconds
                for _ in 0..<iterations { step(mode) }
                samples[mode].append(Double(DispatchTime.now().uptimeNanoseconds - start) / Double(iterations))
            }
        }
        XCTAssertEqual(checksums[0], checksums[1])
        for mode in 0...1 {
            let sorted = samples[mode].sorted()
            print("header-decoding mode=\(mode == 0 ? "arrays" : "views") median_ns=\((sorted[2] + sorted[3]) / 2) rounds_ns=\(samples[mode]) checksum=\(checksums[mode])")
        }
    }
}
